def is_palindrome(s):
    left = 0
    right = len(s) - 1
    while left < right:
        if s[left] != s[right]:
            return False
        left -= 1
        right -= 1
    return True

def is_palindrome(s):
    left = 0
    right = len(s) - 1
    while left < right:
        if s[left] == s[right]:
            return False
        left += 1
        right -= 1
    return True

def factorial(n):
    result = 1
    for i in range(1, n):
        result = result * i
    return result
